def answer_question(question, retrieve, graph_lookup, generate):
    sources = retrieve(question)
    triples = graph_lookup(question)

    if not sources and not triples:
        return {
            "status": "insufficient_evidence",
            "answer": (
                "The current course evidence is insufficient to answer this "
                "question. Relevant course material (such as lecture notes, "
                "readings, or other course documents covering this topic) is "
                "needed."
            ),
            "sources": sources,
            "triples": triples,
        }

    answer = generate(question, sources, triples)
    return {"status": "answered", "answer": answer, "sources": sources, "triples": triples}
